226	  .stabstr       0 : { *(.stabstr) }
227	  .stab.excl     0 : { *(.stab.excl) }
228	  .stab.exclstr  0 : { *(.stab.exclstr) }
229	  .stab.index    0 : { *(.stab.index) }
230	  .stab.indexstr 0 : { *(.stab.indexstr) }
