238	  .line           0 : { *(.line) }
239	  /* GNU DWARF 1 extensions */
240	  .debug_srcinfo  0 : { *(.debug_srcinfo) }
241	  .debug_sfnames  0 : { *(.debug_sfnames) }
242	  /* DWARF 1.1 and DWARF 2 */
243	  .debug_aranges  0 : { *(.debug_aranges) }
244	  .debug_pubnames 0 : { *(.debug_pubnames) }
245	  /* DWARF 2 */
