1	// Multi-entry .vxbin test — device side, C-runtime-prologue edition.
2	//
3	// Three independent kernels in one program, each its own KMU entry point
4	// (see kentry.S). Unlike a bare add/mul pair, these kernels deliberately
5	// depend on state that exists ONLY once __vx_cta_entry's prologue has run:
6	//
7	//   * g_cubes[] is filled by build_cube_table(), registered via
8	//     __attribute__((constructor)) into .init_array. __vx_cta_entry calls
9	//     __libc_init_array, which runs it. Skip that call and g_cubes[] stays
10	//     zero-initialized (.bss) — every result comes out wrong, not crashed.
11	//
12	//   * t_tag (initialized => .tdata) and t_acc (zero-init => .tbss) are
13	//     thread_local. __vx_cta_entry points tp at this hart's own TLS image
14	//     and calls __init_tls, which copies the .tdata template in and zeroes
15	//     .tbss. Having both makes the image span .tdata + .tbss, so the
16	//     per-hart tp stride in vx_start.S must be __tbss_offset + __tbss_size
17	//     — a too-small stride overlaps adjacent harts' images. acc_k reaches
18	//     both through noinline helpers, so the accesses are genuine
19	//     tp-relative loads/stores.
20	//
21	// The multi-entry mechanism (VXSYMTAB footer, per-name resolution, the
22	// shared __vx_cta_entry prologue, vx_enqueue_launch's per-kernel PC) is
23	// exercised — three named kernels resolved out of one .vxbin.
24	//
25	// __vx_cta_entry loads a0 with VX_CSR_MSCRATCH before calling the kernel,
26	// so each kernel takes the kernel_arg_t pointer as its first argument.
27	// This program defines no kernel_main: it is a footer-bearing multi-entry
28	// .vxbin, so vx_start.S's dead _start resolves the weak kernel_main to 0.
29	
30	#include <vx_spawn2.h>
31	#include "common.h"
32	
33	// --- exercises __libc_init_array -------------------------------------------
34	// External linkage + .bss: the compiler cannot prove the post-constructor
35	// contents, so kernel reads stay real loads and the constructor stays an
36	// .init_array entry (never folded into static data).
37	int32_t g_cubes[16];
38	
39	__attribute__((constructor))
40	static void build_cube_table() {
41	  for (int i = 0; i < 16; ++i)
42	    g_cubes[i] = (i + 1) * (i + 1) * (i + 1);   // 1, 8, 27, ..., 4096
43	}
44	
45	// --- exercises __init_tls --------------------------------------------------
46	// t_tag is INITIALIZED, so it lands in .tdata: __init_tls copies that
47	// template into every hart's TLS image. t_acc is zero-init (.tbss). Having
48	// both makes each hart's image span .tdata + .tbss (__tbss_offset > 0) —
49	// the case the per-hart tp stride in vx_start.S must size correctly.
50	thread_local int32_t t_tag = 0x5A5A;
51	thread_local int64_t t_acc;
52	
53	// noinline so the thread-local accesses are emitted as real tp-relative
54	// loads/stores rather than hoisted into plain locals.
55	__attribute__((noinline)) static void    tls_add(int32_t x) { t_acc += x; }
56	__attribute__((noinline)) static int32_t tls_tag()          { return t_tag; }
57	
58	static inline uint32_t global_id() {
59	  return blockIdx.x * blockDim.x + threadIdx.x;
60	}
61	
62	// add_k: dst[i] = src[i] + cubes[i % 16]
63	__kernel void add_k(kernel_arg_t* __UNIFORM__ arg) {
64	  uint32_t i = global_id();
65	  if (i >= arg->count)
66	    return;
67	  auto src = reinterpret_cast<int32_t*>(arg->src_addr);
68	  auto dst = reinterpret_cast<int32_t*>(arg->dst_addr);
69	  dst[i] = src[i] + g_cubes[i & 15];
70	}
71	
72	// mul_k: dst[i] = src[i] * cubes[i % 16]
73	__kernel void mul_k(kernel_arg_t* __UNIFORM__ arg) {
74	  uint32_t i = global_id();
75	  if (i >= arg->count)
76	    return;
77	  auto src = reinterpret_cast<int32_t*>(arg->src_addr);
78	  auto dst = reinterpret_cast<int32_t*>(arg->dst_addr);
79	  dst[i] = src[i] * g_cubes[i & 15];
80	}
81	
82	// acc_k: dst[i] = src[i] + sum_{j=0..7} cubes[(i + j) % 16] + t_tag,
83	// summing through the .tbss accumulator and folding in the .tdata tag.
84	// Correctness needs each hart's TLS image to be private and non-
85	// overlapping: a too-small per-hart stride lets one hart's t_acc writes
86	// stomp a neighbour's t_tag.
87	__kernel void acc_k(kernel_arg_t* __UNIFORM__ arg) {
88	  uint32_t i = global_id();
89	  if (i >= arg->count)
90	    return;
91	  auto src = reinterpret_cast<int32_t*>(arg->src_addr);
92	  auto dst = reinterpret_cast<int32_t*>(arg->dst_addr);
93	  t_acc = 0;                                  // this hart's own .tbss copy
94	  for (uint32_t j = 0; j < 8; ++j)
95	    tls_add(g_cubes[(i + j) & 15]);
96	  dst[i] = src[i] + static_cast<int32_t>(t_acc) + tls_tag();
97	}
