1	// Multi-entry .vxbin test — host side, C-runtime-prologue edition.
2	//
3	// Loads a single .vxbin holding three independent kernels, resolves each
4	// by name via vx_module_get_kernel, and launches all three. Each kernel
5	// depends on state set up by the __vx_cta_entry prologue:
6	//
7	//   add_k / mul_k  read g_cubes[], a table filled by an .init_array
8	//                  constructor (__libc_init_array).
9	//   acc_k          sums g_cubes[] through a .tbss thread_local accumulator
10	//                  and folds in a .tdata thread_local tag (__init_tls +
11	//                  per-hart tp stride).
12	//
13	// So this exercises three things at once and pins a failure to one:
14	//   - the multi-entry mechanism — VXSYMTAB footer parse, per-name
15	//     resolution, vx_enqueue_launch's per-kernel PC;
16	//   - __libc_init_array — if it never runs, g_cubes[] stays zero and
17	//     add_k/mul_k produce src+0 / src*0;
18	//   - __init_tls — if tp is unset or not per-thread, acc_k collides.
19	
20	#include <vortex2.h>
21	#include "common.h"
22	
23	#include <cstdint>
24	#include <cstdio>
25	#include <cstdlib>
26	#include <unistd.h>
27	#include <vector>
28	
29	#define CHECK(expr) do {                                              \
30	    vx_result_t _r = (expr);                                          \
31	    if (_r != VX_SUCCESS) {                                           \
32	      std::fprintf(stderr, "FAIL %s:%d: '%s' returned %s\n",          \
33	                   __FILE__, __LINE__, #expr, vx_result_string(_r));  \
34	      std::exit(1);                                                   \
35	    }                                                                 \
36	  } while (0)
37	
38	#define FAIL(msg) do {                                                \
39	    std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, msg); \
40	    std::exit(1);                                                     \
41	  } while (0)
42	
43	namespace {
44	const char* kernel_file = "kernel.vxbin";
45	uint32_t    size        = 256;
46	
47	void parse_args(int argc, char** argv) {
48	  int c;
49	  while ((c = getopt(argc, argv, "n:k:h")) != -1) {
50	    switch (c) {
51	      case 'n': size        = (uint32_t)std::atoi(optarg); break;
52	      case 'k': kernel_file = optarg;                      break;
53	      default:
54	        std::printf("Usage: [-k kernel] [-n size] [-h]\n");
55	        std::exit(c == 'h' ? 0 : -1);
56	    }
57	  }
58	}
59	
60	// Mirror of the device-side g_cubes[] table: g_cubes[idx] = (idx+1)^3.
61	int32_t cube(uint32_t idx) {
62	  int32_t k = (int32_t)((idx & 15) + 1);
63	  return k * k * k;
64	}
65	} // namespace
66	
67	int main(int argc, char** argv) {
68	  parse_args(argc, argv);
69	  const uint64_t bytes = (uint64_t)size * sizeof(int32_t);
70	  std::printf("multikernel: size=%u\n", size);
71	
72	  vx_device_h dev = nullptr;
73	  CHECK(vx_device_open(0, &dev));
74	
75	  vx_queue_info_t qi = {};
76	  qi.struct_size = sizeof(qi);
77	  qi.priority    = VX_QUEUE_PRIORITY_NORMAL;
78	  vx_queue_h q = nullptr;
79	  CHECK(vx_queue_create(dev, &qi, &q));
80	
81	  vx_buffer_h src_buf = nullptr;
82	  vx_buffer_h add_buf = nullptr, mul_buf = nullptr, acc_buf = nullptr;
83	  CHECK(vx_buffer_create(dev, bytes, VX_MEM_READ,  &src_buf));
84	  CHECK(vx_buffer_create(dev, bytes, VX_MEM_WRITE, &add_buf));
85	  CHECK(vx_buffer_create(dev, bytes, VX_MEM_WRITE, &mul_buf));
86	  CHECK(vx_buffer_create(dev, bytes, VX_MEM_WRITE, &acc_buf));
87	
88	  // Load the multi-entry module and resolve all three kernels by name.
89	  vx_module_h mod = nullptr;
90	  CHECK(vx_module_load_file(dev, kernel_file, &mod));
91	  vx_kernel_h k_add = nullptr, k_mul = nullptr, k_acc = nullptr;
92	  CHECK(vx_module_get_kernel(mod, "add_k", &k_add));
93	  CHECK(vx_module_get_kernel(mod, "mul_k", &k_mul));
94	  CHECK(vx_module_get_kernel(mod, "acc_k", &k_acc));
95	  if (k_add == k_mul || k_add == k_acc || k_mul == k_acc)
96	    FAIL("named kernels resolved to the same handle");
97	
98	  // A name not in the footer must NOT resolve — proves real footer
99	  // lookup, not a single-'main' fallback that would accept anything.
100	  vx_kernel_h k_bogus = nullptr;
101	  if (vx_module_get_kernel(mod, "no_such_kernel", &k_bogus) == VX_SUCCESS)
102	    FAIL("a kernel name absent from the module resolved");
103	
104	  std::vector<int32_t> h_src(size);
105	  std::vector<int32_t> h_add(size, 0), h_mul(size, 0), h_acc(size, 0);
106	  for (uint32_t i = 0; i < size; ++i)
107	    h_src[i] = (int32_t)i;
108	
109	  uint32_t grid[1] = {1}, block[1] = {1};
110	  const uint32_t global_dim[1] = { size };
111	  CHECK(vx_device_max_occupancy_grid(dev, 1, global_dim, grid, block));
112	
113	  kernel_arg_t arg_add = {}, arg_mul = {}, arg_acc = {};
114	  arg_add.count = size;
115	  arg_mul.count = size;
116	  arg_acc.count = size;
117	  CHECK(vx_buffer_address(src_buf, &arg_add.src_addr));
118	  CHECK(vx_buffer_address(add_buf, &arg_add.dst_addr));
119	  CHECK(vx_buffer_address(src_buf, &arg_mul.src_addr));
120	  CHECK(vx_buffer_address(mul_buf, &arg_mul.dst_addr));
121	  CHECK(vx_buffer_address(src_buf, &arg_acc.src_addr));
122	  CHECK(vx_buffer_address(acc_buf, &arg_acc.dst_addr));
123	
124	  CHECK(vx_enqueue_write(q, src_buf, 0, h_src.data(), bytes,
125	                         0, nullptr, nullptr));
126	
127	  // One launch per named kernel, all from the same module. The
128	  // single-worker queue keeps them in submit order.
129	  vx_launch_info_t li_add = {}, li_mul = {}, li_acc = {};
130	  li_add.struct_size = sizeof(li_add);
131	  li_add.kernel      = k_add;
132	  li_add.args_host   = &arg_add;
133	  li_add.args_size   = sizeof(arg_add);
134	  li_add.ndim        = 1;
135	  li_add.grid_dim[0] = grid[0];
136	  li_add.block_dim[0]= block[0];
137	  li_mul = li_add;
138	  li_mul.kernel    = k_mul;
139	  li_mul.args_host = &arg_mul;
140	  li_acc = li_add;
141	  li_acc.kernel    = k_acc;
142	  li_acc.args_host = &arg_acc;
143	
144	  vx_event_h add_ev = nullptr, mul_ev = nullptr, acc_ev = nullptr;
145	  vx_event_h r_add  = nullptr, r_mul  = nullptr, r_acc  = nullptr;
146	  CHECK(vx_enqueue_launch(q, &li_add, 0, nullptr, &add_ev));
147	  CHECK(vx_enqueue_launch(q, &li_mul, 0, nullptr, &mul_ev));
148	  CHECK(vx_enqueue_launch(q, &li_acc, 0, nullptr, &acc_ev));
149	  CHECK(vx_enqueue_read(q, h_add.data(), add_buf, 0, bytes,
150	                        1, &add_ev, &r_add));
151	  CHECK(vx_enqueue_read(q, h_mul.data(), mul_buf, 0, bytes,
152	                        1, &mul_ev, &r_mul));
153	  CHECK(vx_enqueue_read(q, h_acc.data(), acc_buf, 0, bytes,
154	                        1, &acc_ev, &r_acc));
155	  CHECK(vx_event_wait_value(r_add, 1, VX_TIMEOUT_INFINITE));
156	  CHECK(vx_event_wait_value(r_mul, 1, VX_TIMEOUT_INFINITE));
157	  CHECK(vx_event_wait_value(r_acc, 1, VX_TIMEOUT_INFINITE));
158	
159	  int errors = 0;
160	  for (uint32_t i = 0; i < size; ++i) {
161	    int32_t want_add = h_src[i] + cube(i);   // add_k
162	    int32_t want_mul = h_src[i] * cube(i);   // mul_k
163	    int32_t sum = 0;                         // acc_k
164	    for (uint32_t j = 0; j < 8; ++j)
165	      sum += cube(i + j);
166	    int32_t want_acc = h_src[i] + sum + 0x5A5A;   // 0x5A5A = t_tag
167	
168	    if (h_add[i] != want_add) {
169	      if (errors < 8)
170	        std::printf("*** add_k[%u]: got %d, expected %d\n",
171	                    i, h_add[i], want_add);
172	      ++errors;
173	    }
174	    if (h_mul[i] != want_mul) {
175	      if (errors < 8)
176	        std::printf("*** mul_k[%u]: got %d, expected %d\n",
177	                    i, h_mul[i], want_mul);
178	      ++errors;
179	    }
180	    if (h_acc[i] != want_acc) {
181	      if (errors < 8)
182	        std::printf("*** acc_k[%u]: got %d, expected %d\n",
183	                    i, h_acc[i], want_acc);
184	      ++errors;
185	    }
186	  }
187	
188	  vx_event_release(r_acc);
189	  vx_event_release(r_mul);
190	  vx_event_release(r_add);
191	  vx_event_release(acc_ev);
192	  vx_event_release(mul_ev);
193	  vx_event_release(add_ev);
194	  vx_kernel_release(k_acc);
195	  vx_kernel_release(k_mul);
196	  vx_kernel_release(k_add);
197	  vx_module_release(mod);
198	  vx_buffer_release(acc_buf);
199	  vx_buffer_release(mul_buf);
200	  vx_buffer_release(add_buf);
201	  vx_buffer_release(src_buf);
202	  vx_queue_release(q);
203	  vx_device_dump_perf(dev, stdout);
204	  vx_device_release(dev);
205	
206	  if (errors) {
207	    std::printf("Found %d errors!\nFAILED!\n", errors);
208	    return 1;
209	  }
210	  std::printf("PASSED!\n");
211	  return 0;
212	}
